  { ch: 8, id: "c8_mc16", type: "radio", title: "彼得认信后，耶稣首次预言人子受难，内容包括哪些要素？", opts: [
    {v:"a", t:"A. 受许多苦 → 被长老、祭司长和文士弃绝 → 被杀 → 过三天复活"},
    {v:"b", t:"B. 进耶路撒冷作王 → 驱逐罗马总督"},
    {v:"c", t:"C. 被卖给外邦人 → 钉十字架 → 当天升天"},
    {v:"d", t:"D. 召十二营天使降临毁灭仇敌"}
  ], ans: "a", desc: "可 8:31" },
  { ch: 8, id: "c8_mc17", type: "radio", title: "听见受难预言后，谁拉着耶稣责备祂？", opts: [{v:"a",t:"A. 犹大"},{v:"b",t:"B. 彼得"},{v:"c",t:"C. 约翰"},{v:"d",t:"D. 雅各"}], ans: "b", desc: "可 8:32" },
  { ch: 8, id: "c8_mc18", type: "radio", title: "耶稣斥责彼得「撒但，退我后边去吧」，指出的核心罪咎是什么？", opts: [{v:"a",t:"A. 因为彼得偷拿了钱囊"},{v:"b",t:"B. 因为他不体贴神的意思，只体贴人的意思"},{v:"c",t:"C. 因为彼得胆怯害怕风浪"},{v:"d",t:"D. 因为彼得三次不认主"}], ans: "b", desc: "可 8:33" },
  { ch: 8, id: "c8_mc19", type: "radio", title: "跟从耶稣的明确三部曲条件是什么？", opts: [{v:"a",t:"A. 受洗、传道、行神迹"},{v:"b",t:"B. 舍己、背起十字架、跟从我"},{v:"c",t:"C. 变卖产业、周济穷人、住旷野"},{v:"d",t:"D. 禁食、祷告、守律法"}], ans: "b", desc: "可 8:34" },
  { ch: 8, id: "c8_mc20", type: "radio", title: "【数字陷阱】关于四千人吃饱与五千人吃饱的器具与零碎，何者正确？", opts: [
    {v:"a", t:"A. 五千人剩十二筐；四千人剩七篮"},
    {v:"b", t:"B. 五千人剩十二篮；四千人剩七筐"},
    {v:"c", t:"C. 两者都剩十二篮"},
    {v:"d", t:"D. 两者都剩七筐"}
  ], ans: "b", desc: "五千人剩十二篮；四千人剩七筐。" },
  { ch: 8, id: "c8_seq1", type: "radio", title: "【排序题】请按照伯赛大瞎子得医治的动作顺序排列：<br>① 吐唾沫在眼睛上按手 ② 领到村外 ③ 再次按手样样看清 ④ 瞎子说看见人像树木", opts: [{v:"a", t:"A. ② → ① → ④ → ③"},{v:"b", t:"B. ① → ② → ④ → ③"},{v:"c", t:"C. ② → ④ → ① → ③"},{v:"d", t:"D. ① → ④ → ② → ③"}], ans: "a", desc: "可 8:23-25" },
  { ch: 8, id: "c8_seq2", type: "radio", title: "【排序题】请按照彼得认信到受难预言的发展顺序排列：<br>① 耶稣责备彼得为撒但 ② 彼得认耶稣为基督 ③ 耶稣宣告舍己背十字架 ④ 耶稣首次预言受难受死复活", opts: [{v:"a", t:"A. ② → ④ → ① → ③"},{v:"b", t:"B. ② → ① → ④ → ③"},{v:"c", t:"C. ④ → ② → ① → ③"},{v:"d", t:"D. ② → ④ → ③ → ①"}], ans: "a", desc: "可 8:29-34" },
  { ch: 8, id: "c8_seq3", type: "radio", title: "【排序题】请按照四千人吃饱神迹的过程先后排序：<br>① 门徒将零碎装满七个筐子 ② 耶稣祝谢擘开七个饼和鱼递给门徒 ③ 门徒清点有七个饼几条鱼 ④ 众人同在三天困乏", opts: [{v:"a", t:"A. ④ → ③ → ② → ①"},{v:"b", t:"B. ③ → ④ → ② → ①"},{v:"c", t:"C. ④ → ② → ③ → ①"},{v:"d", t:"D. ③ → ② → ④ → ①"}], ans: "a", desc: "可 8:2-8" },
  { ch: 8, id: "c8_seq4", type: "radio", title: "【主线大排序】请按照马可福音第 8 章事件发展排列先后次序：<br>A. 伯赛大瞎子得医治 B. 凯撒利亚·腓立比路上彼得认信 C. 四千人吃饱 D. 防备法利赛人与希律的酵", opts: [{v:"a", t:"A. C → D → A → B"},{v:"b", t:"B. C → A → D → B"},{v:"c", t:"C. D → C → A → B"},{v:"d", t:"D. C → D → B → A"}], ans: "a", desc: "四千人吃饱 → 防备双酵 → 瞎子医治 → 彼得认信。" },
  { ch: 8, id: "c8_mc21", type: "radio", title: "耶稣说凡在这淫乱罪恶的世代把谁当作可耻的，人子降临时也要把那人当作可耻？", opts: [{v:"a",t:"A. 圣殿与祭司"},{v:"b",t:"B. 我和我的道"},{v:"c",t:"C. 十二使徒"},{v:"d",t:"D. 律法与诫命"}], ans: "b", desc: "可 8:38" },
  { ch: 8, id: "c8_mc22", type: "radio", title: "受难预言中，耶稣宣告人子被杀后过几天复活？", opts: [{v:"a",t:"A. 一天"},{v:"b",t:"B. 两天"},{v:"c",t:"C. 三天"},{v:"d",t:"D. 七天"}], ans: "c", desc: "可 8:31" },
  { ch: 8, id: "c8_tf1", type: "tf", title: "四千人吃饱的神迹中，众人是在第一天听完道后立刻领受五饼二鱼的。", ans: "F", desc: "错。同在已经三天。" },
  { ch: 8, id: "c8_tf2", type: "tf", title: "四千人吃饱后，门徒收拾剩下的零碎装满了七个筐子。", ans: "T", desc: "对。可 8:8" },
  { ch: 8, id: "c8_tf3", type: "tf", title: "法利赛人向耶稣求从天上来的神迹，耶稣当场行了一个大天象神迹折服了他们。", ans: "F", desc: "错。耶稣深深叹息并声明没有神迹给这世代看。" },
  { ch: 8, id: "c8_tf4", type: "tf", title: "在船上，耶稣嘱咐门徒要谨慎防备法利赛人的酵和撒都该人的酵。", ans: "F", desc: "错。防备法利赛人的酵和希律的酵。" },
  { ch: 8, id: "c8_tf5", type: "tf", title: "门徒以为耶稣提到酵，是因为责备他们船上忘记带饼。", ans: "T", desc: "对。可 8:16" },
  { ch: 8, id: "c8_tf6", type: "tf", title: "伯赛大瞎子的眼睛在耶稣第一次吐唾沫按手后，就立刻样样都看得极其清楚。", ans: "F", desc: "错。第一次按手看见人好像树木，第二次才完全看清。" },
  { ch: 8, id: "c8_tf7", type: "tf", title: "医好瞎子后，耶稣打发他回家，特别叮嘱他“连这村子你也不要进去”。", ans: "T", desc: "对。可 8:26" },
  { ch: 8, id: "c8_tf8", type: "tf", title: "彼得认信耶稣为基督是在伯赛大会堂里公开发表的声明。", ans: "F", desc: "错。在往凯撒利亚·腓立比村庄的途中。" },
  { ch: 8, id: "c8_tf9", type: "tf", title: "彼得认信说「你是基督」之后，得到了耶稣的高度称赞，并当场吩咐门徒向犹太全地大力宣传。", ans: "F", desc: "错。耶稣禁戒他们不要告诉人。" },
  { ch: 8, id: "c8_tf10", type: "tf", title: "耶稣预言人子必须受许多苦，被长老、祭司长和文士弃绝，被杀后过三天复活。", ans: "T", desc: "对。可 8:31" },
  { ch: 8, id: "c8_tf11", type: "tf", title: "彼得听见受难预言后拉着耶稣劝阻，耶稣斥责他说：“撒但，退我后边去吧！”", ans: "T", desc: "对。可 8:32-33" },
  { ch: 8, id: "c8_tf12", type: "tf", title: "耶稣责备彼得是因为他不体贴神的意思，只体贴人的意思。", ans: "T", desc: "对。可 8:33" },
  { ch: 8, id: "c8_tf13", type: "tf", title: "耶稣教导说：凡要救自己生命的，必救了生命；凡丧掉生命的，必永远灭亡。", ans: "F", desc: "错。救自己生命的必丧掉生命；为福音丧掉生命的必救了生命。" },
  { ch: 8, id: "c8_tf14", type: "tf", title: "人就是赚得全世界，赔上自己的生命，并没有任何益处。", ans: "T", desc: "对。可 8:36" },

  // ==========================================
  // 【第 9 章 全量题目 (全部完整收录)】
  // ==========================================
  { ch: 9, id: "c9_fb1", type: "fill", title: "耶稣在山上变了形像，衣服放光，极其洁白，地上_____的，没有一个能漂得那样白。", blanks: [{id:"c9_f1_1", ans:"漂布|漂布的"}], desc: "可 9:3 地上漂布的，没有一个能漂得那样白。" },
  { ch: 9, id: "c9_fb2", type: "fill", title: "有声音从云彩里出来说：「这是我的_____，你们要_____他。」", blanks: [{id:"c9_f2_1", ans:"爱子"},{id:"c9_f2_2", ans:"听"}], desc: "可 9:7 这是我的爱子，你们要听他。" },
  { ch: 9, id: "c9_fb3", type: "fill", title: "孩子的父亲立时喊着说：「我信！但我_____不足，求主帮助。」", blanks: [{id:"c9_f3_1", ans:"信"}], desc: "可 9:24 我信！但我信不足，求主帮助。" },
  { ch: 9, id: "c9_fb4", type: "fill", title: "耶稣回答门徒赶不出鬼的原因说：「非用_____，这一类的鬼总不能出来。」", blanks: [{id:"c9_f4_1", ans:"祷告"}], desc: "可 9:29 非用祷告，这一类的鬼总不能出来。" },
  { ch: 9, id: "c9_fb5", type: "fill", title: "人子将要被交在人手里，他们要杀害他；被杀以后，过_____天他要复活。", blanks: [{id:"c9_f5_1", ans:"三|3"}], desc: "可 9:31 被杀以后，过三天他要复活。" },
  { ch: 9, id: "c9_fb6", type: "fill", title: "若有人愿意作首先的，他必作众人_____的，作众人的_____。", blanks: [{id:"c9_f6_1", ans:"末后|末后的"},{id:"c9_f6_2", ans:"用人"}], desc: "可 9:35 众人末后的，作众人的用人。" },
  { ch: 9, id: "c9_fb7", type: "fill", title: "耶稣说：「不_____我们的，就是_____我们的。」", blanks: [{id:"c9_f7_1", ans:"敌挡"},{id:"c9_f7_2", ans:"帮助"}], desc: "可 9:40 不敌挡我们的，就是帮助我们的。" },
  { ch: 9, id: "c9_fb8", type: "fill", title: "凡使这信我的一个小子跌倒的，倒不如把_____拴在这人的颈项上，扔在海里。", blanks: [{id:"c9_f8_1", ans:"大磨石"}], desc: "可 9:42 倒不如把大磨石拴在这人的颈项上。" },
  { ch: 9, id: "c9_fb9", type: "fill", title: "在地狱里，_____是不死的，_____是不灭的。", blanks: [{id:"c9_f9_1", ans:"虫"},{id:"c9_f9_2", ans:"火"}], desc: "可 9:48 在那里，虫是不死的，火是不灭的。" },
  { ch: 9, id: "c9_fb10", type: "fill", title: "盐本是好的，若失了味用什么叫它再咸呢？你们里头应当有盐，彼此_____。", blanks: [{id:"c9_f10_1", ans:"和睦"}], desc: "可 9:50 你们里头应当有盐，彼此和睦。" },
  { ch: 9, id: "c9_mc1", type: "radio", title: "耶稣登山变像是在发生受难预言过了几天之后？", opts: [{v:"a",t:"A. 三天"},{v:"b",t:"B. 六天"},{v:"c",t:"C. 七天"},{v:"d",t:"D. 四十天"}], ans: "b", desc: "可 9:2 过了六天，耶稣带着彼得、雅各、约翰。" },
  { ch: 9, id: "c9_mc2", type: "radio", title: "耶稣暗暗带上高山亲眼目睹变像的三位门徒是：", opts: [{v:"a",t:"A. 彼得、安得烈、约翰"},{v:"b",t:"B. 彼得、雅各、约翰"},{v:"c",t:"C. 雅各、约翰、多马"},{v:"d",t:"D. 腓力、巴多罗买、马太"}], ans: "b", desc: "可 9:2 耶稣带着彼得、雅各、约翰暗暗地上了一座高山。" },
  { ch: 9, id: "c9_mc3", type: "radio", title: "在山上向耶稣和三位门徒显现显荣的旧约人物是：", opts: [{v:"a",t:"A. 亚伯拉罕和大卫"},{v:"b",t:"B. 摩西和以利亚"},{v:"c",t:"C. 以诺和以利亚"},{v:"d",t:"D. 撒母耳和以赛亚"}], ans: "b", desc: "可 9:4 忽然，有以利亚同摩西向他们显现。" },
  { ch: 9, id: "c9_mc4", type: "radio", title: "彼得在惊恐不知所措中提议搭几座棚？为谁搭？", opts: [{v:"a",t:"A. 两座棚，为摩西和以利亚"},{v:"b",t:"B. 三座棚，一座为耶稣，一座为摩西，一座为以利亚"},{v:"c",t:"C. 六座棚，大家各住一座"},{v:"d",t:"D. 一座大棚供大家避风"}], ans: "b", desc: "可 9:5 搭三座棚，一座为你，一座为摩西，一座为以利亚。" },
  { ch: 9, id: "c9_mc5", type: "radio", title: "云彩遮盖他们时，天上有声音发出，内容是什么？", opts: [{v:"a",t:"A. 「你是我的爱子，我喜悦你。」"},{v:"b",t:"B. 「这是我的爱子，你们要听他。」"},{v:"c",t:"C. 「凡遵行神旨意的是我的母亲。」"},{v:"d",t:"D. 「你们应当悔改信福音。」"}], ans: "b", desc: "可 9:7 这是我的爱子，你们要听他。" },
  { ch: 9, id: "c9_mc6", type: "radio", title: "下山的时候，耶稣禁戒门徒不要将所看见的告诉人，直到什么时候？", opts: [{v:"a",t:"A. 直到祂进耶路撒冷"},{v:"b",t:"B. 直到人子从死里复活"},{v:"c",t:"C. 直到五旬节圣灵降临"},{v:"d",t:"D. 直到门徒受差遣"}], ans: "b", desc: "可 9:9 耶稣嘱咐他们说：人子还没有从死里复活，你们不要将所看见的告诉人。" },
  { ch: 9, id: "c9_mc7", type: "radio", title: "门徒询问文士为何说以利亚必须先来，耶稣指出以利亚情况如何？", opts: [{v:"a",t:"A. 以利亚绝不会再来"},{v:"b",t:"B. 以利亚已经来了，人们任意待他，正如经上指着他说的"},{v:"c",t:"C. 以利亚将在世界的末了降临"},{v:"d",t:"D. 文士的话是错谬的"}], ans: "b", desc: "可 9:13 以利亚已经来了，他们也任意待他。" },
  { ch: 9, id: "c9_mc8", type: "radio", title: "耶稣与三门徒下山后，看见文士正在和留在山下的门徒做什么？", opts: [{v:"a",t:"A. 彼此擘饼"},{v:"b",t:"B. 辩论"},{v:"c",t:"C. 一同祷告"},{v:"d",t:"D. 查考摩西律法"}], ans: "b", desc: "可 9:14 见有许多人围着他们，又有文士和他们辩论。" },
  { ch: 9, id: "c9_mc9", type: "radio", title: "那父亲带来的孩子被什么鬼附着？", opts: [{v:"a",t:"A. 哑巴鬼"},{v:"b",t:"B. 癫痫鬼"},{v:"c",t:"C. 瞎眼鬼"},{v:"d",t:"D. 群鬼"}], ans: "a", desc: "可 9:17 我带了我的儿子到你这里来，他被哑巴鬼附着。" },
  { ch: 9, id: "c9_mc10", type: "radio", title: "孩子的父亲求耶稣说“你若能作什么求你帮助”，耶稣的回应是：", opts: [{v:"a",t:"A. 「神的心意是不可测度的」"},{v:"b",t:"B. 「你若能信，在信的人，凡事都能」"},{v:"c",t:"C. 「我肯，你洁净了吧」"},{v:"d",t:"D. 「平平安安地回去吧」"}], ans: "b", desc: "可 9:23 耶稣对他说：你若能信，在信的人，凡事都能。" },
  { ch: 9, id: "c9_mc11", type: "radio", title: "听见耶稣责备污鬼后，孩子抽疯仿佛死人，耶稣如何医治使他站起？", opts: [{v:"a",t:"A. 泼凉水在脸上"},{v:"b",t:"B. 拉着他的手，扶他起来"},{v:"c",t:"C. 吩咐门徒抬回家中"},{v:"d",t:"D. 用油抹他的身体"}], ans: "b", desc: "可 9:27 但耶稣拉着他的手，扶他起来，他就站起来了。" },
  { ch: 9, id: "c9_mc12", type: "radio", title: "山下的门徒赶不出那哑巴鬼，耶稣在屋里点出的根本原因是：", opts: [{v:"a",t:"A. 门徒没有背诵律法"},{v:"b",t:"B. 非用祷告，这一类的鬼总不能出来"},{v:"c",t:"C. 门徒缺乏禁食天数"},{v:"d",t:"D. 孩子的父亲未奉献"}], ans: "b", desc: "可 9:29 非用祷告，这一类的鬼总不能出来。" },
  { ch: 9, id: "c9_mc13", type: "radio", title: "第二次预言受难时，门徒的真实反应是什么？", opts: [{v:"a",t:"A. 立即放声大哭"},{v:"b",t:"B. 明白过来并深信"},{v:"c",t:"C. 不明白这话，又不敢问祂"},{v:"d",t:"D. 极力劝阻耶稣"}], ans: "c", desc: "可 9:32 门徒却不明白这话，又不敢问他。" },
  { ch: 9, id: "c9_mc14", type: "radio", title: "门徒在去往哪个城镇的路上争论谁为大？", opts: [{v:"a",t:"A. 伯赛大"},{v:"b",t:"B. 迦百农"},{v:"c",t:"C. 耶路撒冷"},{v:"d",t:"D. 耶利哥"}], ans: "b", desc: "可 9:33 他们来到迦百农。耶稣在屋里问他们说：你们在路上议论的是什么？" },
  { ch: 9, id: "c9_mc15", type: "radio", title: "在屋里教导谁为大时，耶稣特别抱起了谁作为榜样？", opts: [{v:"a",t:"A. 彼得"},{v:"b",t:"B. 一个小孩子"},{v:"c",t:"C. 穷寡妇"},{v:"d",t:"D. 乞丐"}], ans: "b", desc: "可 9:36 于是领一个小孩子来，叫他站在门徒中间，又抱起他来。" },
  { ch: 9, id: "c9_mc16", type: "radio", title: "约翰告诉耶稣他们禁止了一个人，是因为那人做了什么？", opts: [{v:"a",t:"A. 传讲虚假教义"},{v:"b",t:"B. 奉耶稣的名赶鬼，却不跟从门徒"},{v:"c",t:"C. 在安息日作工"},{v:"d",t:"D. 不肯给门徒水喝"}], ans: "b", desc: "可 9:38 我们看见一个人奉你的名赶鬼，我们就禁止他，因为他不跟从我们。" },
  { ch: 9, id: "c9_mc17", type: "radio", title: "面对门徒的狭隘排他，耶稣给出的教导准则是：", opts: [{v:"a",t:"A. 「凡不入十二使徒团的一概是异端」"},{v:"b",t:"B. 「不要禁止他；因为不敌挡我们的，就是帮助我们的」"},{v:"c",t:"C. 「叫他们立刻受割礼」"},{v:"d",t:"D. 「召火从天上降下显明真伪」"}], ans: "b", desc: "可 9:39-40 不要禁止他...不敌挡我们的，就是帮助我们的。" },
  { ch: 9, id: "c9_mc18", type: "radio", title: "凡因门徒是属基督，给门徒一杯什么喝的，不能不得赏赐？", opts: [{v:"a",t:"A. 新酒"},{v:"b",t:"B. 水"},{v:"c",t:"C. 橄榄油"},{v:"d",t:"D. 羊奶"}], ans: "b", desc: "可 9:41 凡因你们是属基督，给你们一杯水喝的...不能不得赏赐。" },
  { ch: 9, id: "c9_mc19", type: "radio", title: "为防止叫人跌倒或自己跌倒，耶稣教导对付犯罪器官的严格顺序是：", opts: [
    {v:"a", t:"A. 眼 → 手 → 脚"},
    {v:"b", t:"B. 手 → 脚 → 眼"},
    {v:"c", t:"C. 脚 → 手 → 眼"},
    {v:"d", t:"D. 舌头 → 手 → 心"}
  ], ans: "b", desc: "可 9:43(手砍下) → 45(脚砍下) → 47(眼剜出)。" },
  { ch: 9, id: "c9_mc20", type: "radio", title: "【数字陷阱】在第 9 章登山变像的故事中，以下哪组数字完全准确？", opts: [
    {v:"a", t:"A. 过了三天上山；搭三座棚"},
    {v:"b", t:"B. 过了六天上山；搭三座棚"},
    {v:"c", t:"C. 过了六天上山；搭两座棚"},
    {v:"d", t:"D. 过了七天上山；搭三座棚"}
  ], ans: "b", desc: "可 9:2 过了六天；可 9:5 搭三座棚。" },
  { ch: 9, id: "c9_seq1", type: "radio", title: "【排序题】请按照登山变像的过程先后排序：<br>① 云彩遮盖有声音说这是我的爱子 ② 门徒忽然不见一人只见耶稣 ③ 耶稣衣服放光摩西以利亚显现 ④ 彼得提议搭三座棚", opts: [{v:"a", t:"A. ③ → ④ → ① → ②"},{v:"b", t:"B. ④ → ③ → ① → ②"},{v:"c", t:"C. ③ → ① → ④ → ②"},{v:"d", t:"D. ① → ③ → ④ → ②"}], ans: "a", desc: "变像显现(9:3-4) → 提议搭棚(9:5) → 云彩声音(9:7) → 只见耶稣(9:8)。" },
  { ch: 9, id: "c9_seq2", type: "radio", title: "【排序题】请按照山下医治被鬼附孩子的事件发展排序：<br>① 父亲求告说我信但我信不足 ② 门徒暗暗问为何赶不出鬼 ③ 耶稣斥责聋哑鬼拉手扶起孩子 ④ 文士与山下门徒辩论", opts: [{v:"a", t:"A. ④ → ① → ③ → ②"},{v:"b", t:"B. ① → ④ → ③ → ②"},{v:"c", t:"C. ④ → ③ → ① → ②"},{v:"d", t:"D. ④ → ① → ② → ③"}], ans: "a", desc: "文士辩论(9:14) → 信不足呼求(9:24) → 斥责扶起(9:25-27) → 屋内发问(9:28)。" },
  { ch: 9, id: "c9_seq3", type: "radio", title: "【排序题】请按照门徒争论谁为大的事件发展排序：<br>① 耶稣问路上议论什么门徒不作声 ② 耶稣抱起小孩子教训接待原则 ③ 耶稣坐下召十二门徒论首先与末后 ④ 门徒在去迦百农路上彼此争论谁为大", opts: [{v:"a", t:"A. ④ → ① → ③ → ②"},{v:"b", t:"B. ① → ④ → ③ → ②"},{v:"c", t:"C. ④ → ③ → ① → ②"},{v:"d", t:"D. ① → ③ → ④ → ②"}], ans: "a", desc: "路上争大(9:34) → 屋内发问(9:33) → 坐下训诲(9:35) → 抱小孩子(9:36)。" },
  { ch: 9, id: "c9_seq4", type: "radio", title: "【全章主线大排序】请按照马可福音第 9 章事件发展次序排列：<br>A. 山下赶出哑巴鬼 B. 门徒争论谁为大与抱小孩子 C. 登山变像 D. 手脚眼防跌倒与盐", opts: [{v:"a", t:"A. C → A → B → D"},{v:"b", t:"B. A → C → B → D"},{v:"c", t:"C. C → B → A → D"},{v:"d", t:"D. C → A → D → B"}], ans: "a", desc: "变像(9:2) → 赶鬼(9:14) → 争大(9:33) → 手脚眼与盐(9:43-50)。" },
  { ch: 9, id: "c9_mc21", type: "radio", title: "如果一只眼睛叫你跌倒，耶稣给出的处理决断是什么？", opts: [{v:"a",t:"A. 闭上眼"},{v:"b",t:"B. 砍下来"},{v:"c",t:"C. 剜出来"},{v:"d",t:"D. 戴上面纱"}], ans: "c", desc: "可 9:47 倘若你一只眼叫你跌倒，就去掉它（剜出来）。" },
  { ch: 9, id: "c9_mc22", type: "radio", title: "第 9 章末尾，耶稣对门徒之间内部相处的劝勉总结是：", opts: [{v:"a",t:"A. 谨守安息日"},{v:"b",t:"B. 彼此和睦"},{v:"c",t:"C. 凡事谢恩"},{v:"d",t:"D. 设立监督"}], ans: "b", desc: "可 9:50 你们里头应当有盐，彼此和睦。" },
  { ch: 9, id: "c9_tf1", type: "tf", title: "马可福音 9:1 预言站在这里的所有门徒，都在没尝死味前看见神的国大有能力临到。", ans: "F", desc: "错。经文明确说明是「有人」在没尝死味以前，非全员。" },
  { ch: 9, id: "c9_tf2", type: "tf", title: "登山变像时，与耶稣同在山上显现谈论的是摩西和以利亚。", ans: "T", desc: "对。可 9:4 经文完全吻合。" },
  { ch: 9, id: "c9_tf3", type: "tf", title: "彼得提议搭三座棚，是因为他心中十分清醒并有智慧的属灵计划。", ans: "F", desc: "错。可 9:6 彼得不知道说什么才好，因为他们甚是惧怕。" },
  { ch: 9, id: "c9_tf4", type: "tf", title: "登山变像中云彩发出的声音是说：「这是我的爱子，你们要听他。」", ans: "T", desc: "对。可 9:7 经文完全吻合。" },
  { ch: 9, id: "c9_tf5", type: "tf", title: "下山的时候，耶稣允许门徒把山上所见到的异象立刻向犹太全地大力宣告。", ans: "F", desc: "错。可 9:9 耶稣嘱咐他们：人子还没有从死里复活，不要将所看见的告诉人。" },
  { ch: 9, id: "c9_tf6", type: "tf", title: "被哑巴鬼附着的孩子，从生下来懂事起，门徒就屡次轻易把他治好。", ans: "F", desc: "错。山下门徒赶不出那鬼，孩子从小屡次受苦。" },
  { ch: 9, id: "c9_tf7", type: "tf", title: "孩子的父亲对耶稣呼喊说：「我信！但我信不足，求主帮助。」", ans: "T", desc: "对。可 9:24 经文完全吻合。" },
  { ch: 9, id: "c9_tf8", type: "tf", title: "耶稣向门徒指明，赶出这一类顽固的污鬼，非用祷告总不能出来。", ans: "T", desc: "对。可 9:29 经文完全吻合。" },
  { ch: 9, id: "c9_tf9", type: "tf", title: "第二次受难预言时，耶稣说人子被杀以后，过七天要复活。", ans: "F", desc: "错。可 9:31 明确是「过三天」他要复活。" },
  { ch: 9, id: "c9_tf10", type: "tf", title: "门徒在去迦百农的路上，暗暗地彼此争论谁为大。", ans: "T", desc: "对。可 9:34 经文完全吻合。" },
  { ch: 9, id: "c9_tf11", type: "tf", title: "耶稣说，若有人愿意作首先的，他就必受众人的服事。", ans: "F", desc: "错。可 9:35 他必作众人末后的，作众人的用人。" },
  { ch: 9, id: "c9_tf12", type: "tf", title: "使徒约翰曾因看见有人奉主名赶鬼却不跟从门徒，就出手禁止了那人。", ans: "T", desc: "对。可 9:38 经文完全吻合。" },
  { ch: 9, id: "c9_tf13", type: "tf", title: "耶稣宣告：不敌挡我们的，就是帮助我们的。", ans: "T", desc: "对。可 9:40 经文完全吻合。" },
  { ch: 9, id: "c9_tf14", type: "tf", title: "耶稣说哪怕一只手叫人跌倒，也当忍耐保留，不可造成身体残缺。", ans: "F", desc: "错。可 9:43 明确教导应当砍下来，宁可缺肢体进入永生。" }

 // ==========================================
 // 【第 10 章 全量题目 (50 题)】
 // ==========================================
  {
    ch: 10,
    id: "c10_match1",
    type: "matching",
    title: "第十章经文前半句与后半句配对：",
    pairs: [
      { id: "c10_p1", left: "但从起初创造的时候，神造人是造男造女。", rightText: "因此，人要离开父母，与妻子连合，二人成为一体。" },
      { id: "c10_p2", left: "耶稣看着他，就爱他，对他说：“你还缺少一件：去变卖你所有的，分给穷人，", rightText: "就必有财宝在天上；你还要来跟从我。”" },
      { id: "c10_p3", left: "耶稣看着他们，说：“在人是不能，在神却不然，", rightText: "因为神凡事都能。”" },
      { id: "c10_p4", left: "人子将要被交给祭司长和文士，他们要定祂死罪，交给外邦人。", rightText: "他们要戏弄祂，吐唾沫在祂脸上，鞭打祂，杀害祂；过了三天，祂要复活。" },
      { id: "c10_p5", left: "你们中间谁愿为大，就必作你们的用人；", rightText: "在你们中间谁愿为首，就必作众人的仆人。" },
      { id: "c10_p6", left: "因为人子来，并不是要受人的服事，", rightText: "乃是要服事人，并且要舍命作多人的赎价。" },
      { id: "c10_p7", left: "耶稣说：“你去吧！你的信救了你了。”", rightText: "瞎子立刻看见了，就在路上跟随耶稣。" }
    ]
  },
  { ch: 10, id: "c10_fb1", type: "fill", title: "法利赛人来试探耶稣，问祂说：「人休妻可以不可以？」耶稣反问说：「_____吩咐你们的是什么？」", blanks: [{id:"c10_f1_1", ans:"摩西"}], desc: "可 10:3 摩西吩咐你们的是什么？" },
  { ch: 10, id: "c10_fb2", type: "fill", title: "耶稣说：摩西写这诫命，是因为你们的心_____。", blanks: [{id:"c10_f2_1", ans:"硬"}], desc: "可 10:5 因为你们的心硬，摩西才写这诫命。" },
  { ch: 10, id: "c10_fb3", type: "fill", title: "耶稣说：所以，神所配合的，人不可_____。", blanks: [{id:"c10_f3_1", ans:"分开"}], desc: "可 10:9 神所配合的，人不可分开。" },
  { ch: 10, id: "c10_fb4", type: "fill", title: "耶稣看见就恼怒，对门徒说：让_____到我这里来，不要禁止他们。", blanks: [{id:"c10_f4_1", ans:"小孩子"}], desc: "可 10:14 让小孩子到我这里来。" },
  { ch: 10, id: "c10_fb5", type: "fill", title: "凡要承受神国的，若不像_____，断不能进去。", blanks: [{id:"c10_f5_1", ans:"小孩子"}], desc: "可 10:15 若不像小孩子断不能进去。" },
  { ch: 10, id: "c10_fb6", type: "fill", title: "富足人来问永生，耶稣说：你为什么称我是_____？除了神一位之外，再没有_____。", blanks: [{id:"c10_f6_1", ans:"良善"},{id:"c10_f6_2", ans:"良善"}], desc: "可 10:18 为什么称我是良善的。" },
  { id: "c10_fb7", type: "fill", title: "那人对耶稣说：「夫子，这一切我_____都遵守了。」", blanks: [{id:"c10_f7_1", ans:"从小"}], desc: "可 10:20 这一切我从小都遵守了。" },
  { id: "c10_fb8", type: "fill", title: "耶稣看着他，就_____他，吩咐他变卖所有分给穷人来跟从祂。", blanks: [{id:"c10_f8_1", ans:"爱"}], desc: "可 10:21 耶稣看着他，就爱他。" },
  { id: "c10_fb9", type: "fill", title: "耶稣说：_____穿过针的眼，比财主进神的国还容易呢。", blanks: [{id:"c10_f9_1", ans:"骆驼"}], desc: "可 10:25 骆驼穿过针的眼。" },
  { id: "c10_fb10", type: "fill", title: "耶稣看着他们说：在人是不能，在神却不然，因为神凡事都_____。", blanks: [{id:"c10_f10_1", ans:"能"}], desc: "可 10:27 在神凡事都能。" },
  { id: "c10_fb11", type: "fill", title: "然而，有许多在_____将要在_____，在_____将要在_____。", blanks: [{id:"c10_f11_1", ans:"前"},{id:"c10_f11_2", ans:"后"},{id:"c10_f11_3", ans:"后"},{id:"c10_f11_4", ans:"前"}], desc: "可 10:31 在前的将要在后，在后的将要在前。" },
  { id: "c10_fb12", type: "fill", title: "谁愿为大，就必作你们的_____；在你们中间谁愿为首，就必作众人的_____。", blanks: [{id:"c10_f12_1", ans:"用人"},{id:"c10_f12_2", ans:"仆人"}], desc: "可 10:43-44 愿为大作仆人用人。" },
  { id: "c10_fb13", type: "fill", title: "因为人子来，并不是要受人的服事，乃是要_____人，并且要舍命作多人的_____。", blanks: [{id:"c10_f13_1", ans:"服事"},{id:"c10_f13_2", ans:"赎价"}], desc: "可 10:45 舍命作多人的赎价。" },
  { id: "c10_fb14", type: "fill", title: "出耶利哥时，有一个讨饭的瞎子，名叫_____，是底买的儿子。", blanks: [{id:"c10_f14_1", ans:"巴底买"}], desc: "可 10:46 瞎子巴底买。" },
  { id: "c10_fb15", type: "fill", title: "瞎子听见是拿撒勒的耶稣，就喊着说：_____的子孙耶稣啊，可怜我吧！", blanks: [{id:"c10_f15_1", ans:"大卫"}], desc: "可 10:47 大卫的子孙耶稣可怜我吧。" },
  { id: "c10_fb16", type: "fill", title: "瞎子丢下衣服，跳起来，走到耶稣那里说：「_____，我要能看见。」", blanks: [{id:"c10_f16_1", ans:"拉波尼"}], desc: "可 10:51 拉波尼，我要能看见。" },
  { id: "c10_fb17", type: "fill", title: "耶稣说：「你去吧！你的_____救了你了。」瞎子立刻看见了，在路上跟随耶稣。", blanks: [{id:"c10_f17_1", ans:"信"}], desc: "可 10:52 你的信救了你了。" },
  { id: "c10_fb18", type: "fill", title: "「神所配合的，人不可分开」出现在马可福音第 10 章第_____节。", blanks: [{id:"c10_f18_1", ans:"9|9节|10:9"}], desc: "可 10:9 婚姻金句。" },
  { id: "c10_mc1", type: "radio", title: "法利赛人来试探耶稣，向祂提出的休妻问题背景在什么地方？", opts: [{v:"a",t:"A. 迦百农会堂"},{v:"b",t:"B. 犹太境内、约旦河外"},{v:"c",t:"C. 撒玛利亚村庄"},{v:"d",t:"D. 耶路撒冷圣殿"}], ans: "b", desc: "可 10:1 到了犹太境内并约旦河外。" },
  { id: "c10_mc2", type: "radio", title: "法利赛人向耶稣发问的实际原话问题是：", opts: [{v:"a",t:"A. 男人可不可以休妻？"},{v:"b",t:"B. 人休妻可以不可以？"},{v:"c",t:"C. 犯奸淫的妻子可否被休？"},{v:"d",t:"D. 摩西为何禁止休妻？"}], ans: "b", desc: "可 10:2 问祂说：人休妻可以不可以？" },
  { id: "c10_mc3", type: "radio", title: "耶稣指出摩西准许写休书的根本原因是什么？", opts: [{v:"a",t:"A. 律法不够完全"},{v:"b",t:"B. 因为他们的心硬"},{v:"c",t:"C. 为了保护妇女权益"},{v:"d",t:"D. 罗马政权的要求"}], ans: "b", desc: "可 10:5 耶稣说：摩西写这诫命，是因为你们的心硬。" },
  { id: "c10_mc4", type: "radio", title: "当门徒责备带小孩子来的人时，耶稣的反应是：", opts: [{v:"a",t:"A. 默许赞同"},{v:"b",t:"B. 甚是恼怒"},{v:"c",t:"C. 叹息忧愁"},{v:"d",t:"D. 严厉斥责门徒不要再讲道"}], ans: "b", desc: "可 10:14 耶稣看见就恼怒。" },
  { id: "c10_mc5", type: "radio", title: "耶稣对待被带到面前的小孩子的具体动作包括：（多选）", opts: [{v:"a",t:"A. 抱着小孩子"},{v:"b",t:"B. 给他们按手"},{v:"c",t:"C. 为他们祝福"},{v:"d",t:"D. 给他们受洗"}], ans: ["a","b","c"], desc: "可 10:16 于是抱着小孩子，把手按在他们身上，为他们祝福。" },
  { id: "c10_mc6", type: "radio", title: "跑来跪在耶稣面前求问永生的人，当耶稣说出诫命时他如何回答？", opts: [{v:"a",t:"A. 「我都做不到」"},{v:"b",t:"B. 「这一切我从小都遵守了」"},{v:"c",t:"C. 「哪一条诫命最大」"},{v:"d",t:"D. 「我不明白诫命」"}], ans: "b", desc: "可 10:20 这一切我从小都遵守了。" },
  { id: "c10_mc7", type: "radio", title: "听见变卖产业分给穷人并跟从主的吩咐后，那富足的人有什么反应？", opts: [{v:"a",t:"A. 欢欢喜喜照办"},{v:"b",t:"B. 脸上变了色，忧忧愁愁地走了"},{v:"c",t:"C. 当场受洗"},{v:"d",t:"D. 拿出一半财产"}], ans: "b", desc: "可 10:22 他听见这话，脸上就变了色，忧忧愁愁地走了。" },
  { id: "c10_mc8", type: "radio", title: "第三次预言受难时，耶稣走在前头，门徒和跟从的人表现如何？", opts: [{v:"a",t:"A. 欢呼歌唱"},{v:"b",t:"B. 门徒惊奇，跟从的人也害怕"},{v:"c",t:"C. 争论谁为大"},{v:"d",t:"D. 准备逃跑"}], ans: "b", desc: "可 10:32 门徒惊奇，跟从的人也害怕。" },
  { id: "c10_mc9", type: "radio", title: "西庇太的儿子雅各和约翰向耶稣求的是什么？", opts: [{v:"a",t:"A. 赐给他们降火的能力"},{v:"b",t:"B. 在荣耀里一个坐右边一个坐左边"},{v:"c",t:"C. 赐给他们管钱袋的权柄"},{v:"d",t:"D. 求能看见天开"}], ans: "b", desc: "可 10:37 一个坐在你右边，一个坐在你左边。" },
  { id: "c10_mc10", type: "radio", title: "听见雅各和约翰的自私祈求后，其余十个门徒有什么表现？", opts: [{v:"a",t:"A. 赞同支持"},{v:"b",t:"B. 恼怒雅各和约翰"},{v:"c",t:"C. 默不做声"},{v:"d",t:"D. 替他们代求"}], ans: "b", desc: "可 10:41 那十个门徒听见就恼怒雅各、约翰。" },
  { id: "c10_mc11", type: "radio", title: "瞎子巴底买听见耶稣叫他时，他的动作细节是：", opts: [{v:"a",t:"A. 慢慢爬过去"},{v:"b",t:"B. 丢下衣服，跳起来，走到耶稣那里"},{v:"c",t:"C. 请门徒扶他过去"},{v:"d",t:"D. 站在原地哭泣"}], ans: "b", desc: "可 10:50 就丢下衣服，跳起来，走到耶稣那里。" },
  { id: "c10_mc12", type: "radio", title: "【动作排序】瞎子巴底买得医治的过程顺序排列何者正确？<br>① 丢下衣服跳起来走到耶稣那里 ② 听见是耶稣大声喊大卫的子孙 ③ 耶稣说你的信救了你立刻看见跟随 ④ 众人责备他不许作声他越发大声", opts: [{v:"a", t:"A. ② → ④ → ① → ③"},{v:"b", t:"B. ④ → ② → ① → ③"},{v:"c", t:"C. ② → ① → ④ → ③"},{v:"d", t:"D. ① → ② → ④ → ③"}], ans: "a", desc: "呼喊(10:47) → 众人责备越发大声(10:48) → 跳起走去(10:50) → 信救了你立刻跟随(10:52)。" },
  { id: "c10_mc13", type: "radio", title: "【顺序排序】富有的人求永生的事件顺序排列：<br>② 脸上变色忧忧愁愁地走了 ③ 跑来跪在耶稣面前问永生 ④ 回答从小遵守诫命 ① 耶稣爱他吩咐变卖所有分给穷人", opts: [{v:"a", t:"A. ③ → ④ → ① → ②"},{v:"b", t:"B. ④ → ③ → ① → ②"},{v:"c", t:"C. ③ → ① → ④ → ②"},{v:"d", t:"D. ① → ③ → ④ → ②"}], ans: "a", desc: "跑来跪下(10:17) → 从小遵守(10:20) → 耶稣爱他吩咐变卖(10:21) → 忧愁离开(10:22)。" },
  { id: "c10_mc14", type: "radio", title: "【第三次受难预言顺序】受难细节顺序排列：<br>① 交给外邦人戏弄吐唾沫鞭打 ② 祭司长文士定死罪 ③ 三天后复活 ④ 杀害", opts: [{v:"a", t:"A. ② → ① → ④ → ③"},{v:"b", t:"B. ① → ② → ④ → ③"},{v:"c", t:"C. ② → ④ → ① → ③"},{v:"d", t:"D. ② → ① → ③ → ④"}], ans: "a", desc: "定死罪(10:33) → 外邦人戏弄鞭打(10:34) → 杀害(10:34) → 复活(10:34)。" },
  { id: "c10_tf1", type: "tf", title: "耶稣说，从起初创造的时候，神造人是造男造女，神所配合的人不可分开。", ans: "T", desc: "对。可 10:6, 9 经文完全吻合。" },
  { id: "c10_tf2", type: "tf", title: "当门徒阻拦小孩子就近耶稣时，耶稣大为赞赏门徒维护了会堂秩序。", ans: "F", desc: "错。可 10:14 耶稣看见就恼怒。" },
  { id: "c10_tf3", type: "tf", title: "那个求问永生的富有之人，耶稣看着他就恨他假冒为善。", ans: "F", desc: "错。可 10:21 耶稣看着他，就爱他。" },
  { id: "c10_tf4", type: "tf", title: "耶稣宣告：在人是不能，在神却不然，因为神凡事都能。", ans: "T", desc: "对。可 10:27 经文完全吻合。" },
  { id: "c10_tf5", type: "tf", title: "耶稣教导门徒：谁愿为大，就当操权管束别人。", ans: "F", desc: "错。可 10:43 谁愿为大，就必作你们的用人。" },
  { id: "c10_tf6", type: "tf", title: "人子来不是要受人的服事，乃是要服事人，并且要舍命作多人的赎价。", ans: "T", desc: "对。可 10:45 经文完全吻合。" },
  { id: "c10_tf7", type: "tf", title: "瞎子巴底买双眼得看见后，立刻欢欢喜喜回自己家里去了，不再跟从任何人。", ans: "F", desc: "错。可 10:52 瞎子立刻看见了，就在路上跟随耶稣。" }
  
 // ==========================================
